import csv,hashlib,io,json,re
from pathlib import Path
BASE=Path(__file__).resolve().parent;raw=Path('/workspace/benchmark-results/20261022_ixkn_v2_down_M64_W8_channel_candidate_tianshu')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
assert (raw/'profiler_exit.txt').read_text().strip()=='0';app=json.loads((raw/'app/result.json').read_text());assert app['complete'] and app['pre_profile_output_verified'] and app['post_profile_output_verified'];assert all(sha(p)==h for p,h in app['sources'].items())
text=(raw/'metrics.csv').read_text().splitlines();i=next(i for i,s in enumerate(text) if s.startswith('"Kernel ID"'));rows=list(csv.DictReader(io.StringIO('\n'.join(text[i:]))));assert len(rows)>=90 and all(set(r)=={'Kernel ID','Process ID','Process Name','Kernel Name','Context','Stream','Section','Metrics','Value'} and all(v is not None for v in r.values()) for r in rows)
assert {r['Kernel ID'] for r in rows}=={'0'} and {r['Kernel Name'] for r in rows}=={'_matmul'} and {r['Process ID'] for r in rows}=={str(app['runner_pid'])}
metrics={r['Section']+'/'+r['Metrics']:r['Value'] for r in rows if r['Metrics'] not in ('INF','WRN','OPT')};sections=sorted({r['Section'] for r in rows});assert len(sections)==8
keys={'duration_ns':'GPU Speed Of Light/Duration','tcu_efficiency':'GPU Speed Of Light/TCU Efficiency','dram_read_efficiency':'GPU Speed Of Light/Dram Read Efficiency','grid':'Launch Statistics/Grid Size','block':'Launch Statistics/Block Size','vector_registers':'Launch Statistics/Vector Register','shared_bytes':'Launch Statistics/Dynamic Shared Memory','occupancy':'Occupancy/Achieved Occupancy','waves':'Occupancy/Waves Per CU','no_eligible':'Scheduler Statistics/No Eligible'}
selected={name:metrics[key] for name,key in keys.items()};number=lambda x:float(re.match(r'[-+.0-9]+',x).group())
assert number(selected['shared_bytes'])==app['compiled']['shared'] and number(selected['vector_registers'])==app['compiled']['n_regs'];expected_grid=((int(app['M'])+app['configuration']['bm']-1)//app['configuration']['bm'])*((2048+app['configuration']['bn']-1)//app['configuration']['bn']);assert selected['grid']==f'[{expected_grid}, 1, 1]';assert selected['block']==f'[{app["configuration"]["warps"]*64}, 1, 1]'
component=float(app['component_graph_median_ms']['candidate_ms']);assert abs(number(selected['duration_ns'])/1.e6-component)<.15*component
reference=json.loads((Path(app['raw_reference'])/'result.json').read_text());case=next(c for c in reference['cases'] if (c['role'],c['format'],c['M'],c['configuration'])==(app['role'],app['format'],app['M'],app['configuration']));assert app['compiled']['binary_sha256']==case['compiled']['binary_sha256']
result=dict(complete=True,CPU_only=True,tool_exit=0,app_output_before_after_verified=True,actual_binary_equals_audited_component=True,kernels=1,metric_rows=len(rows),available_sections=sections,selected_metrics=selected,CSV_sha256=sha(raw/'metrics.csv'),app_result_sha256=sha(raw/'app/result.json'),metrics=metrics,interpretation_limit='SDK-reported metrics; not every estimated detailed-set metric is assumed available, and occupancy denominator definitions are not hardware proof.',raw_directory=str(raw))
(BASE/'PROFILE_GATE_32g.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:result[k] for k in ('complete','metric_rows','selected_metrics')}))
